import "server-only";
import { APP_NAME } from "@/lib/config";
import { getEnv } from "@/server/lib/env";
import { OG_IMAGE_ALT, OG_IMAGE_PATH, OG_IMAGE_SIZE } from "@/server/marketing/metadata";
import type { SiteContext } from "./page-seo";

/**
 * Product name, public origin and the site-wide social card (generated by `src/app/opengraph-image.tsx`) for metadata
 * and JSON-LD. Build-time values only: no request data.
 */
export function siteContext(): SiteContext {
  return {
    appName: APP_NAME,
    appUrl: getEnv().APP_URL,
    image: { url: OG_IMAGE_PATH, width: OG_IMAGE_SIZE.width, height: OG_IMAGE_SIZE.height, alt: OG_IMAGE_ALT },
  };
}
